// Both sweeps feed the same sender: people to ask, and manager copies that never went out.
const asks = $input.all().filter(i => (i.json || {}).appointment_id !== undefined);
let retries = [];
try { retries = $('Manager copies still owed').all().filter(i => (i.json || {}).appointment_id !== undefined); }
catch (e) { retries = []; }
return asks.concat(retries);

const sent = $input.all().map(i => i.json || {});
const completed = (($('Mark finished appointments complete').first().json || {}).result || {}).completed;
const by = sent.reduce((a, s) => { const k = s.reason || 'unknown'; a[k] = (a[k] || 0) + 1; return a; }, {});
return [{ json: { ran_at: new Date().toISOString(), marked_completed: completed,
                  review_requests: sent.length, by_outcome: by } }];
